mapper.select:
select id, stat_date, funnel_code as funnel_name, step_code as step_name, case step_code when 'community_post_impression' then 1 when 'community_post_open' then 2 when 'community_post_qualified_view' then 3 when 'content_view' then 1 when 'search_submit' then 1 when 'content_like' then case when funnel_code = 'community_post_engagement' then 4 else 2 end when 'content_favorite' then case when funnel_code = 'community_post_engagement' then 5 else 3 end when 'content_share' then case when funnel_code = 'community_post_engagement' then 6 else 4 end when 'signup_start' then 4 when 'signup_submit' then 5 when 'payment_success' then 6 when 'template_reuse' then 7 when 'topic_publish_success' then 8 when 'activity_publish_success' then 9 when 'coupon_verify' then 10 when 'withdrawal_submit' then 11 else 99 end as step_order, source as biz_type, city_code, user_count as member_count, event_count, conversion_rate, create_time from biz_funnel_daily
and funnel_code = #{funnelName} and source = #{bizType} and city_code = #{cityCode} and stat_date >= #{params.beginStatDate} and stat_date <= #{params.endStatDate}
order by stat_date desc, funnel_code asc, step_order asc
